class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            dp[i] = dp[i-1] + 1
            for j in range(1, i):
                valid = True
                for k in range(j, i):
                    if (k > j and abs(ord(word[k]) - ord(word[k-1])) <= 1) :
                        valid = False
                        break
                    if k == j and abs(ord(word[k]) - ord(word[k-1])) <= 1 and j > 1:
                        valid = False
                        break
                    
                if valid:
                    dp[i] = min(dp[i], dp[j-1] + (i-j) - (len([ 1 for k in range(j,i) if word[k] == word[k-1] and k > j-1]) if j>0 else 0))

        ans = dp[n]
        return ans
